package com.endpoint.frelog.domain.canvas.github;
import com.endpoint.frelog.domain.canvas.service.*;
import com.endpoint.frelog.domain.canvas.dto.CanvasUpdateDtos;
import com.endpoint.frelog.global.security.CustomUserDetails;
import com.endpoint.frelog.global.exception.*;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import java.nio.file.*;
import java.nio.channels.FileChannel;
import java.util.*;

/** GitHub credentials stay in the browser. Server-side policy gates application actions. */
@Service
public class CanvasGithubService {
 public static final Set<String> USER_ACTIONS=Set.of("commit","push","pr","create_branch","switch_branch");
 private final CanvasService canvases;private final CanvasResourceService resources;private final ObjectMapper json=new ObjectMapper();
 public record Target(String owner,String repo,String path){}
 public record Branch(Integer canvasId,boolean initialized,Long createdBy){public Branch(Integer id,boolean ready){this(id,ready,null);}}
 public record Project(Target target,Map<String,Branch> branches,Map<String,Set<String>> permissions){public Project{if(branches==null)branches=new LinkedHashMap<>();if(permissions==null)permissions=new LinkedHashMap<>();}public Project(Target target,Map<String,Branch> branches){this(target,branches,new LinkedHashMap<>());}}
 public record Bind(String owner,String repo,String path,String branch){}
 public record BranchRequest(String branch,@JsonProperty("canvas_password_token") String passwordToken){public BranchRequest(String branch){this(branch,null);}}
 public record Policy(Map<String,Set<String>> groups){}
 public record Action(String action,String owner,String repo,String path,String branch){}
 public CanvasGithubService(CanvasService canvases,CanvasResourceService resources){this.canvases=canvases;this.resources=resources;}
 private Path directory(int id){return resources.getCanvasDirectory(id);}
 private int root(int id)throws Exception{Path p=directory(id).resolve("github-root.json");return Files.exists(p)?json.readTree(p.toFile()).path("rootId").asInt(id):id;}
 private Project read(int id)throws Exception{Path p=directory(id).resolve("github-project.json");return Files.exists(p)?json.readValue(p.toFile(),Project.class):new Project(null,new LinkedHashMap<>());}
 private void write(Path path,Object value)throws Exception{Files.createDirectories(path.getParent());Path tmp=Files.createTempFile(path.getParent(),"github-",".tmp");try{json.writeValue(tmp.toFile(),value);try{Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp);}}
 private Set<String> memberships(CanvasUpdateDtos.SettingsResponse settings,CustomUserDetails user){Set<String> result=new HashSet<>();settings.groups().forEach((name,members)->{if(members.stream().anyMatch(m->Objects.equals(m.nickname(),user.getNickname())&&Objects.equals(m.tagNumber(),user.getUser().getTagNumber())))result.add(name);});if("public".equals(settings.visibility())&&settings.groupPermissions().containsKey(settings.initialGroup()))result.add(settings.initialGroup());return result;}
 private Map<String,Boolean> capabilities(int id,CustomUserDetails user,Project p){var settings=canvases.getCanvasSettings(id,user);var members=memberships(settings,user);boolean admin=settings.canManage();boolean write=admin||members.stream().anyMatch(g->settings.groupPermissions().getOrDefault(g,Map.of()).getOrDefault("write",false));var result=new LinkedHashMap<String,Boolean>();for(String a:USER_ACTIONS)result.put(a,admin||members.stream().anyMatch(g->p.permissions().getOrDefault(g,Set.of()).contains(a)));if(!write)result.put("create_branch",false);for(String a:List.of("manage","restore","merge"))result.put(a,admin);return result;}
 private void require(int root,Project p,String action,CustomUserDetails user){if(!Boolean.TRUE.equals(capabilities(root,user,p).get(action)))throw new CustomException(ErrorCode.ACCESS_DENIED,"GitHub 작업 권한이 없습니다: "+action);}
 private void branch(String s){if(s==null||s.isBlank()||s.length()>200||s.contains("..")||s.contains("@{")||s.startsWith("/")||s.endsWith("/")||s.endsWith(".")||s.chars().anyMatch(c->c<=32||"~^:?*[\\".indexOf(c)>=0))throw new CustomException(ErrorCode.INVALID_INPUT_VALUE,"브랜치 이름을 확인하세요.");}
 private void target(Bind b){branch(b.branch());if(b.owner()==null||!b.owner().matches("[A-Za-z0-9][A-Za-z0-9-]{0,38}")||b.repo()==null||!b.repo().matches("[A-Za-z0-9_.-]{1,100}")||b.path()==null||b.path().length()>1000||!b.path().endsWith(".json")||Arrays.stream(b.path().split("/",-1)).anyMatch(s->s.isEmpty()||s.equals(".")||s.equals("..")||s.chars().anyMatch(c->c<32||"\\?#".indexOf(c)>=0)))throw new CustomException(ErrorCode.INVALID_INPUT_VALUE,"저장소 경로를 확인하세요.");}
 public synchronized Map<String,Object> context(int id,CustomUserDetails user){try{canvases.getCanvasSettings(id,user);int root=root(id);var settings=canvases.getCanvasSettings(root,user);Project p=read(root);var members=memberships(settings,user);return Map.of("rootId",root,"project",p,"currentBranch",p.branches().entrySet().stream().filter(e->e.getValue().canvasId().equals(id)).map(Map.Entry::getKey).findFirst().orElse(""),"capabilities",capabilities(root,user,p),"groups",settings.groupPermissions().keySet(),"readGroups",members.stream().filter(g->settings.groupPermissions().getOrDefault(g,Map.of()).getOrDefault("read",false)).toList());}catch(CustomException e){throw e;}catch(Exception e){throw new CustomException(ErrorCode.INTERNAL_SERVER_ERROR,"브랜치 연결 정보를 읽지 못했습니다.");}}
 private interface Work<T>{T run(int root,Project p)throws Exception;}
 private synchronized <T>T mutate(int id,CustomUserDetails user,Work<T> work){try{canvases.getCanvasSettings(id,user);int root=root(id);canvases.getCanvasSettings(root,user);Files.createDirectories(directory(root));try(var channel=FileChannel.open(directory(root).resolve("github-project.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);var lock=channel.lock()){return work.run(root,read(root));}}catch(CustomException e){throw e;}catch(Exception e){throw new CustomException(ErrorCode.INTERNAL_SERVER_ERROR,"브랜치 연결 정보를 저장하지 못했습니다.");}}
 public Map<String,Object> bind(int id,Bind b,CustomUserDetails user){target(b);return mutate(id,user,(root,p)->{require(root,p,"manage",user);Target t=new Target(b.owner().toLowerCase(Locale.ROOT),b.repo().toLowerCase(Locale.ROOT),b.path());var entries=new LinkedHashMap<>(p.branches());String old=entries.entrySet().stream().filter(e->e.getValue().canvasId().equals(id)).map(Map.Entry::getKey).findFirst().orElse(null);if(old==null&&!entries.isEmpty())throw new CustomException(ErrorCode.ACCESS_DENIED);if(old!=null&&!old.equals(b.branch())){if(entries.containsKey(b.branch()))throw new CustomException(ErrorCode.INVALID_INPUT_VALUE,"다른 캔버스에 연결된 브랜치입니다.");var value=entries.remove(old);entries.put(b.branch(),value);}if(entries.isEmpty())entries.put(b.branch(),new Branch(id,true));write(directory(root).resolve("github-project.json"),new Project(t,entries,p.permissions()));return context(id,user);});}
 public Map<String,Object> policy(int id,Policy policy,CustomUserDetails user){return mutate(id,user,(root,p)->{require(root,p,"manage",user);if(policy.groups()==null||policy.groups().size()>64)throw new CustomException(ErrorCode.INVALID_INPUT_VALUE);var known=canvases.getCanvasSettings(root,user).groupPermissions().keySet();for(var e:policy.groups().entrySet())if(!known.contains(e.getKey())||e.getValue()==null||!USER_ACTIONS.containsAll(e.getValue()))throw new CustomException(ErrorCode.INVALID_INPUT_VALUE,"GitHub 그룹 권한을 확인하세요.");write(directory(root).resolve("github-project.json"),new Project(p.target(),p.branches(),policy.groups()));return context(id,user);});}
 public Map<String,Object> authorize(int id,Action a,CustomUserDetails user){try{int root=root(id);canvases.getCanvasSettings(id,user);Project p=read(root);require(root,p,a.action(),user);if(p.target()==null||!p.target().equals(new Target(a.owner().toLowerCase(Locale.ROOT),a.repo().toLowerCase(Locale.ROOT),a.path()))||!p.branches().containsKey(a.branch())||!p.branches().get(a.branch()).canvasId().equals(id))throw new CustomException(ErrorCode.ACCESS_DENIED,"관리자가 연결한 저장소와 현재 브랜치에서만 작업할 수 있습니다.");return context(id,user);}catch(CustomException e){throw e;}catch(Exception e){throw new CustomException(ErrorCode.INVALID_INPUT_VALUE);}}
 public Branch checkout(int id,BranchRequest b,CustomUserDetails user){branch(b.branch());canvases.verifyBranchSourcePassword(id,user,b.passwordToken());return mutate(id,user,(root,p)->{if(p.target()==null)throw new CustomException(ErrorCode.INVALID_INPUT_VALUE,"먼저 저장소를 연결하세요.");Branch existing=p.branches().get(b.branch());require(root,p,existing!=null?"switch_branch":"create_branch",user);if(existing!=null){canvases.getCanvasSettings(existing.canvasId(),user);return existing;}if(p.branches().size()>=128)throw new CustomException(ErrorCode.INVALID_INPUT_VALUE,"프로젝트는 최대 128개 브랜치 캔버스를 지원합니다.");var child=canvases.createBranchCanvas(id,b.branch(),user);Branch created=new Branch(child.canvasId(),false,user.getUserId());write(directory(child.canvasId()).resolve("github-root.json"),Map.of("rootId",root));var entries=new LinkedHashMap<>(p.branches());entries.put(b.branch(),created);write(directory(root).resolve("github-project.json"),new Project(p.target(),entries,p.permissions()));return created;});}
 public Map<String,Object> checkoutResponse(int id,BranchRequest b,CustomUserDetails user){Branch result=checkout(id,b,user);var response=new LinkedHashMap<String,Object>();response.put("canvasId",result.canvasId());response.put("initialized",result.initialized());response.put("canvas_password_token",canvases.inheritedBranchPasswordGrant(id,result.canvasId(),user,b.passwordToken()));return response;}
 public void initialized(int id,BranchRequest b,CustomUserDetails user){mutate(id,user,(root,p)->{Branch entry=p.branches().get(b.branch());if(entry==null)throw new CustomException(ErrorCode.INVALID_INPUT_VALUE);var caps=capabilities(root,user,p);if(!caps.get("manage")&&(!caps.get("create_branch")||!Objects.equals(entry.createdBy(),user.getUserId())))throw new CustomException(ErrorCode.ACCESS_DENIED);var entries=new LinkedHashMap<>(p.branches());entries.put(b.branch(),new Branch(entry.canvasId(),true,entry.createdBy()));write(directory(root).resolve("github-project.json"),new Project(p.target(),entries,p.permissions()));return true;});}
}
